arguments.command:
cat << 'EOF' > explore2.py
import pandas as pd
df = pd.read_csv('alloy_pair_constrained_train.csv')
for col in df.columns:
    if df[col].dtype in ['float64', 'int64']:
        print(f"{col}: min={df[col].min()}, max={df[col].max()}")
    else:
        print(f"{col}: {df[col].unique()}")
EOF
python explore2.py

